[ExtensionOf(formStr(EssLeaveRequestEntry))]
internal final class NVEssLeaveRequestEntry_Extension
{
    private HcmWorker locCallerWorker;

}

Method.Source:
public void init()
{
    next init();

    if (this.args().caller())
    {
        EssICommonMethods essCommon = this.args().caller() as EssICommonMethods;

        if (essCommon)
        {
            DirPersonRecId callerPerson = essCommon.getDirPersonCallerRecId();
            locCallerWorker = HcmWorker::findByPerson(callerPerson);
        }
        else
        {
            Common record = this.args().record();

            if (record && record.TableId == tableNum(HcmWorker))
            {
                locCallerWorker = HcmWorker::find(record.RecId);
            }
        }
    }

}

public void initBalanceDetails()
{
    LeaveTypeRecId currrentLeaveType = LeaveType.value();
    real totalDays;
    LeaveRequestDetailTmp_ds.observe();

    LeaveRequestDetailTmp currentRow = LeaveRequestDetailTmp_ds.getFirst();
    while (currentRow)
    {
        totalDays += currentRow.Amount - currentRow.ExistingAmount;

        currentRow = LeaveRequestDetailTmp_ds.getNext();
    }

    NVLeaveBalanceDetailsTmp detailsTmp = NVLeaveBalanceDetailsTmp::balanceByLeaveType(locCallerWorker.RecId, EndDate.dateValue(), currrentLeaveType, StartDate.dateValue(), totalDays);

    NVLeaveBalanceDetailsTmp.setTmpData(detailsTmp);
    NVLeaveBalanceDetailsTmp_ds.executeQuery();
    NVLeaveBalanceDetailsTmp_ds.research(true);
}
